{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "Ensure ALB protocol is HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The listener is configured to use HTTP on port 80, which does not encrypt traffic. This exposes sensitive data to potential interception."
    },
    {
      "check_id": "CKV_AWS_103",
      "title": "Ensure that load balancer is using at least TLS 1.2",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The listener is not configured to use HTTPS, which means it cannot enforce a minimum TLS version. This could allow insecure connections."
    }
  ],
  "patched_code": "resource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = \"443\"\n  protocol          = \"HTTPS\"\n  ssl_policy        = \"ELBSecurityPolicy-TLS-1-2-2017-01\"\n  certificate_arn   = \"arn:aws:acm:region:account-id:certificate/certificate-id\"\n\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}",
  "fix_summary": "Updated the listener to use HTTPS on port 443, added an SSL policy enforcing TLS 1.2, and included a placeholder for the certificate ARN."
}
